#!/usr/bin/env python3
"""Print a project file's stored elements one per line (and optionally other sections).
usage: els.py file [section...]
"""
import json, sys
d = json.load(open(sys.argv[1]))
secs = sys.argv[2:]
if not secs:
    for k, e in d['elements'].items():
        print(k, json.dumps(e, ensure_ascii=False))
    print('top keys:', list(d.keys()))
else:
    for s in secs:
        print(s, json.dumps(d.get(s), ensure_ascii=False, indent=1))

